('qb-ref-java-001','Spring 默认事务回滚规则','Spring 声明式事务默认如何处理 RuntimeException、Error 和检查型异常？','JAVA','foundation','STANDARD',
 JSON_ARRAY('Spring','事务','异常'),JSON_ARRAY('RuntimeException 默认回滚','Error 默认回滚','检查型异常默认不回滚'),
 '默认规则下，RuntimeException 及其子类会触发事务回滚，Error 也会触发回滚。检查型异常默认不触发回滚。需要改变这一规则时，可以通过 @Transactional 的 rollbackFor 指定应触发回滚的异常类型。',
 JSON_ARRAY('认为所有 Exception 都会默认回滚','认为 Error 不属于默认回滚范围'),JSON_ARRAY('rollbackFor 用来指定什么？','检查型异常与运行期异常的默认回滚行为有何区别？'),
 'EXTERNAL_REFERENCE','JavaGuide《Spring 事务详解》：事务回滚规则','https://javaguide.cn/system-design/framework/spring/spring-transaction.html'),
('qb-ref-java-002','Spring 事务代理与自调用','为什么同一个类中直接调用带 @Transactional 的另一个方法，可能无法应用该方法声明的事务规则？','JAVA','foundation','STANDARD',
 JSON_ARRAY('Spring','AOP','事务代理'),JSON_ARRAY('Spring AOP 基于代理拦截','同类直接调用不经过代理','拆分类职责可避免自调用'),
 'Spring AOP 的事务增强由代理执行。同一对象中的直接方法调用没有经过代理，因此被调用方法上的 @Transactional 不会在这次调用中触发新的事务增强。可以拆分类职责，让调用经过另一个 Bean 的代理；原文也列出了使用 AspectJ 的方式。',
 JSON_ARRAY('认为只要方法标注注解就一定被增强','把同类直接调用当成经过代理的外部调用'),JSON_ARRAY('事务增强在哪一层执行？','拆分 Bean 后调用路径发生了什么变化？'),
 'EXTERNAL_REFERENCE','JavaGuide《Spring 事务详解》：Spring AOP 自调用问题','https://javaguide.cn/system-design/framework/spring/spring-transaction.html'),
('qb-ref-java-003','JdbcTemplate 保留哪些业务代码','《Spring 实战》第 5 版的 JDBC 示例中，JdbcTemplate 去除了哪些样板代码，调用方仍需完成什么？','JAVA','foundation','BEGINNER',
 JSON_ARRAY('Spring','JdbcTemplate','JDBC'),JSON_ARRAY('简化连接和语句管理','简化 JDBC 资源清理','保留 SQL 查询与结果映射'),
 'JdbcTemplate 封装了创建连接、创建语句以及关闭连接、语句和结果集等重复工作。书中的 queryForObject 示例保留 SQL、查询参数和行映射函数，调用方主要关注执行什么查询，以及如何把结果映射为领域对象。',
 JSON_ARRAY('认为使用 JdbcTemplate 就不需要 SQL','认为结果到领域对象的映射会自动消失'),JSON_ARRAY('书中使用哪个方法执行单对象查询？','行映射函数负责什么？'),
 'EXTERNAL_REFERENCE','《Spring 实战》第 5 版，3.1 使用 JDBC 读取和写入数据，PDF 第 130–132 页','https://www.manning.com/books/spring-in-action-fifth-edition'),
('qb-ref-java-004','JMS 与 JmsTemplate 的职责','《Spring 实战》第 5 版如何区分 JMS 标准、消息代理和 JmsTemplate？','JAVA','foundation','BEGINNER',
 JSON_ARRAY('Spring','JMS','JmsTemplate'),JSON_ARRAY('JMS 定义通用 Java 消息 API','代理传递生产者和消费者之间的消息','JmsTemplate 支持队列与主题消息'),
 'JMS 是定义消息代理通用 API 的 Java 标准，使遵从规范的实现使用共同接口。消息代理负责在生产者和消费者之间传递消息。Spring 的 JmsTemplate 在 JMS 之上提供模板抽象，用于发送和接收队列或主题消息。',
 JSON_ARRAY('把 JMS 标准当成某一个代理产品','把 JmsTemplate 当成消息存储代理'),JSON_ARRAY('JMS 为什么有助于不同代理之间复用代码？','JmsTemplate 支持哪两类消息目的地？'),
 'EXTERNAL_REFERENCE','《Spring 实战》第 5 版，8.1 使用 JMS 发送消息，PDF 第 313 页','https://www.manning.com/books/spring-in-action-fifth-edition'),
('qb-ref-database-001','读提交隔离级别的边界','读提交隔离级别能避免哪种读异常，还可能出现哪两种读异常？','DATABASE','storage','BEGINNER',
 JSON_ARRAY('MySQL','事务','隔离级别'),JSON_ARRAY('只读取其他事务已提交的修改','避免脏读','仍可能不可重复读和幻读'),
 '读提交要求其他事务的修改在提交后才对当前读取可见，因此可以避免脏读。同一事务内的后续读取仍可能看到其他事务新提交的修改，所以不能据此排除不可重复读和幻读。',
 JSON_ARRAY('把读提交等同于可重复读','认为避免脏读就避免了所有读异常'),JSON_ARRAY('脏读读取的是哪类事务的数据？','为什么同一事务内两次读取仍可能不同？'),
 'EXTERNAL_REFERENCE','JavaGuide《MySQL 事务隔离级别详解》：事务隔离级别总结','https://javaguide.cn/database/mysql/transaction-isolation-level.html'),
('qb-ref-database-002','覆盖索引为什么能减少回表','什么是覆盖索引？查询所需字段都在索引中时，为什么可以减少回表？','DATABASE','storage','STANDARD',
 JSON_ARRAY('MySQL','覆盖索引','回表'),JSON_ARRAY('索引包含查询需要的字段','直接从索引取得结果','避免再访问完整数据行'),
 '覆盖索引指查询需要的字段都可以从所使用的索引中取得。对于原本需要通过二级索引再定位数据行的查询，索引已经提供了所需字段时，就可以直接返回结果，避免为了补齐字段再回表。覆盖与否取决于具体查询需要哪些列。',
 JSON_ARRAY('认为建立任何索引都能避免回表','只看过滤列而忽略查询返回的列'),JSON_ARRAY('查询增加一个不在索引中的返回列会怎样？','覆盖索引描述的是索引与什么之间的关系？'),
 'EXTERNAL_REFERENCE','JavaGuide《MySQL 索引详解》：覆盖索引','https://javaguide.cn/database/mysql/mysql-index.html'),
('qb-ref-database-003','undo log 如何撤销增删改','《图解 MySQL》中，插入、删除和更新记录分别需要在 undo log 中保留什么回滚信息？','DATABASE','storage','STANDARD',
 JSON_ARRAY('MySQL','undo log','事务回滚'),JSON_ARRAY('插入记录保存主键','删除记录保存原内容','更新记录保存被更新列的旧值'),
 '插入时记录主键，回滚时删除对应记录；删除时记录原记录内容，回滚时重新插入；更新时记录被修改列的旧值，回滚时恢复旧值。undo log 按操作类型保存撤销所需的信息，通过反向操作恢复数据，支撑事务原子性。',
 JSON_ARRAY('认为三种操作的 undo 内容完全一样','把 undo log 的主要用途说成主从复制'),JSON_ARRAY('删除记录的回滚为什么需要保存整条记录内容？','undo log 支撑哪项事务特性？'),
 'EXTERNAL_REFERENCE','小林 coding《图解 MySQL》v2.0，5.1 日志，PDF 第 296–297 页','https://xiaolincoding.com/mysql/log/how_update.html'),
('qb-ref-database-004','三种 MySQL 日志的层次与用途','undo log、redo log 和 binlog 分别由哪一层生成，主要解决什么问题？','DATABASE','storage','BEGINNER',
 JSON_ARRAY('MySQL','日志','InnoDB'),JSON_ARRAY('undo log 用于回滚与 MVCC','redo log 用于故障恢复和持久性','binlog 用于备份与主从复制'),
 'undo log 和 redo log 由 InnoDB 存储引擎层生成：前者主要用于事务回滚与 MVCC，支撑原子性；后者主要用于掉电等故障恢复，支撑持久性。binlog 由 MySQL Server 层生成，主要用于数据备份和主从复制。',
 JSON_ARRAY('认为 binlog 是 InnoDB 专有日志','把 redo log 和 undo log 的职责对调'),JSON_ARRAY('哪一种日志不属于存储引擎层？','事务回滚与掉电恢复分别主要依靠什么日志？'),
 'EXTERNAL_REFERENCE','小林 coding《图解 MySQL》v2.0，5.1 日志，PDF 第 295 页','https://xiaolincoding.com/mysql/log/how_update.html'),
('qb-ref-database-005','ReadView 与 undo 版本链','MySQL 的快照读如何利用 ReadView 和 undo log 找到可见的历史记录？','DATABASE','storage','ADVANCED',
 JSON_ARRAY('MySQL','MVCC','ReadView'),JSON_ARRAY('事务标识记录修改者','回滚指针串联历史版本','ReadView 决定版本可见性'),
 '记录中的事务标识用于识别修改该版本的事务，回滚指针把 undo log 中的历史版本串成版本链。快照读按 ReadView 判断版本可见性；当前版本不满足时，沿版本链查找可见的历史版本。undo log 因而既用于回滚，也是 MVCC 的组成部分。',
 JSON_ARRAY('认为快照读只能读取最新版本','认为有历史版本就不需要可见性判断'),JSON_ARRAY('版本链通过什么指针连接？','undo log 除了参与 MVCC 还有什么用途？'),
 'EXTERNAL_REFERENCE','小林 coding《图解 MySQL》v2.0，5.1 日志，PDF 第 298–299 页','https://xiaolincoding.com/mysql/log/how_update.html'),
('qb-ref-database-006','区分三种并发读异常','《图解 MySQL》如何区分脏读、不可重复读和幻读？','DATABASE','storage','BEGINNER',
 JSON_ARRAY('MySQL','脏读','幻读'),JSON_ARRAY('脏读涉及未提交修改','不可重复读关注同一数据前后变化','幻读关注符合条件的记录集合变化'),
 '脏读是读到其他事务尚未提交的修改。不可重复读是同一事务内多次读取同一数据，前后结果不同。书中通过同一查询条件下记录数量变化来说明幻读，强调它关注符合条件的记录集合，而不只是某一条记录的值。',
 JSON_ARRAY('把读到已提交的新值也称为脏读','把单条记录值变化与结果集变化混为一谈'),JSON_ARRAY('脏读中的写事务为什么可能使读取结果失效？','原文用哪种查询结果变化解释幻读？'),
 'EXTERNAL_REFERENCE','小林 coding《图解 MySQL》v2.0，3.1 事务隔离级别，PDF 第 156–158 页','https://xiaolincoding.com/mysql/transaction/mvcc.html'),
('qb-ref-redis-001','本地缓存为何不能直接跨实例共享','本地缓存部署在多个应用实例时，为什么不能像共享缓存服务那样直接共享同一份数据？','REDIS','storage','BEGINNER',
 JSON_ARRAY('本地缓存','多实例','Redis'),JSON_ARRAY('缓存位于各实例内存','实例之间数据独立','同一数据可能存在多个副本'),
 '本地缓存保存在应用实例自己的内存中，各实例各自维护数据。一个实例写入或删除本地缓存，不会直接修改其他实例的内存。因此多实例部署会存在多份缓存副本，跨实例共享和一致性需要额外的协调机制。',
 JSON_ARRAY('认为使用同一个缓存库就共享同一块内存','认为一个实例失效缓存会自动同步全部实例'),JSON_ARRAY('本地缓存的数据存在哪里？','多实例下同一个键为什么可能返回不同值？'),
 'EXTERNAL_REFERENCE','JavaGuide《缓存基础常见面试题总结》：本地缓存有什么痛点？','https://javaguide.cn/database/redis/cache-basics.html'),
('qb-ref-redis-002','多级缓存的失效传播','同时使用 JVM 本地缓存与 Redis 时，仅删除 Redis 为什么不能清除所有旧值？TTL 在其中起什么作用？','REDIS','storage','ADVANCED',
 JSON_ARRAY('多级缓存','本地缓存','TTL'),JSON_ARRAY('本地副本独立存在','失效通知需要传播到各实例','TTL 限制旧副本存活时间'),
 '删除 Redis 中的键不会自动删除每个 JVM 中的本地副本，本地命中仍可能返回旧值。原文讨论通过消息通知等方式传播本地失效，并配合较短 TTL 缩短旧副本的存活时间。TTL 提供过期收敛，不能代替跨实例的失效传播。',
 JSON_ARRAY('认为删除 Redis 就清除了所有缓存层','认为 TTL 与失效通知作用完全相同'),JSON_ARRAY('失效通知需要到达哪些实例？','本地 TTL 能改变已经返回的旧值吗？'),
 'EXTERNAL_REFERENCE','JavaGuide《缓存基础常见面试题总结》：多级缓存一致性如何保证？','https://javaguide.cn/database/redis/cache-basics.html'),
('qb-ref-redis-003','Cache Aside 的更新顺序与事务提交','Cache Aside 中“先更新数据库，再删除缓存”的数据库更新完成，为什么应包含事务提交？','REDIS','storage','STANDARD',
 JSON_ARRAY('Cache Aside','事务提交','缓存一致性'),JSON_ARRAY('SQL 执行与事务提交不同','提前删除可能回填旧值','删除应发生在成功提交之后'),
 'UPDATE 执行完并不代表事务已提交。如果提交前先删除缓存，并发读可能从数据库读到旧的已提交值，再把旧值填回缓存。原文因此将“先更新数据库”解释为更新并成功提交事务，再执行缓存删除。',
 JSON_ARRAY('把 UPDATE 返回当成事务已经提交','认为事务内删除缓存一定不会回填旧值'),JSON_ARRAY('提前删缓存后，并发读可能从哪里取得旧值？','事务提交与 SQL 执行的区别是什么？'),
 'EXTERNAL_REFERENCE','JavaGuide《3 种常用的缓存读写策略详解》：Cache Aside Pattern','https://javaguide.cn/database/redis/3-commonly-used-cache-read-and-write-strategies.html'),
('qb-ref-redis-004','Write Through 与 Write Behind','Read/Write Through 和 Write Behind 在数据库写入时机上有什么区别？','REDIS','storage','STANDARD',
 JSON_ARRAY('缓存策略','Write Through','Write Behind'),JSON_ARRAY('Through 同步更新缓存与数据库','Behind 先更新缓存','Behind 异步批量写数据库'),
 'Read/Write Through 由缓存服务封装数据库读写，写入时同步更新缓存和数据库。Write Behind 则先更新缓存，再异步、批量地把修改写入数据库。两者的核心差别是数据库写入是否同步完成，后者存在缓存与数据库暂时不同步的阶段。',
 JSON_ARRAY('认为 Write Behind 每次都同步写数据库','把异步批量写入理解为永远不落数据库'),JSON_ARRAY('哪种策略更容易合并多次数据库写入？','Write Behind 为什么会有暂时不一致？'),
 'EXTERNAL_REFERENCE','JavaGuide《3 种常用的缓存读写策略详解》：Write Behind Pattern','https://javaguide.cn/database/redis/3-commonly-used-cache-read-and-write-strategies.html'),
('qb-ref-redis-005','Redis 为何组合两种过期删除策略','Redis 为什么将惰性删除与定期删除配合使用？两者分别何时检查键？','REDIS','storage','BEGINNER',
 JSON_ARRAY('Redis','过期删除','TTL'),JSON_ARRAY('惰性删除在访问时检查','定期删除随机检查过期键','平衡 CPU 时间与内存占用'),
 '惰性删除在访问键时检查是否过期，开销较小，但一直不再访问的过期键仍占内存。定期删除每隔一段时间随机抽取一批键，检查并删除已过期的键。两者配合，在 CPU 时间和过期数据占用的内存之间取得平衡。',
 JSON_ARRAY('认为过期瞬间一定立即物理删除','认为定期删除每次都遍历全部键'),JSON_ARRAY('只用惰性删除对内存有什么影响？','定期删除为什么要限制执行时长和频率？'),
 'EXTERNAL_REFERENCE','小林 coding《图解 Redis》v2.0，过期删除策略，PDF 第 231–232 页','https://xiaolincoding.com/redis/module/strategy.html'),
('qb-ref-redis-006','过期删除与内存淘汰的区别','Redis 的过期删除和内存淘汰分别针对什么问题？volatile-lru 的候选键范围是什么？','REDIS','storage','STANDARD',
 JSON_ARRAY('Redis','内存淘汰','LRU'),JSON_ARRAY('过期删除清理已过期键','内存超限触发淘汰策略','volatile-lru 仅从设置过期时间的键中选择'),
 '过期删除针对已经到期的键。内存淘汰在运行内存超过配置的最大内存后，按策略处理符合条件的键。volatile-lru 的候选集合是设置了过期时间的键，再从中选择最久未使用者；这些候选键并不要求已经过期。',
 JSON_ARRAY('认为内存淘汰只能删除已过期键','把 volatile-lru 的范围理解为全部键'),JSON_ARRAY('哪条命令可以查看 maxmemory-policy？','过期时间与最近使用时间决定的是同一件事吗？'),
 'EXTERNAL_REFERENCE','小林 coding《图解 Redis》v2.0，内存淘汰策略，PDF 第 238–240 页','https://xiaolincoding.com/redis/module/strategy.html'),
('qb-ref-concurrency-001','线程池核心线程、队列与扩容','ThreadPoolExecutor 收到新任务时，核心线程数、任务队列和最大线程数通常按什么顺序参与调度？','CONCURRENCY','concurrency','BEGINNER',
 JSON_ARRAY('Java','线程池','任务队列'),JSON_ARRAY('未达核心线程数时创建线程','达到核心线程数后尝试入队','队列满后尝试扩容至最大线程数'),
 '线程数小于核心线程数时创建线程执行任务；达到核心线程数后，通常先尝试把任务加入队列。队列无法接收时，再尝试增加线程直到最大线程数；线程和队列均无法接收新任务时，执行拒绝策略。核心线程默认按需创建。',
 JSON_ARRAY('认为达到核心线程数就直接扩容到最大值','认为构造线程池时所有核心线程都已创建'),JSON_ARRAY('队列容量会怎样影响扩容时机？','什么条件下会进入拒绝策略？'),
 'EXTERNAL_REFERENCE','JavaGuide《Java 线程池详解》：线程池参数分析','https://javaguide.cn/java/concurrent/java-thread-pool-summary.html'),
('qb-ref-concurrency-002','Future 等待超时与任务取消','Future.get 的超时和 Future.cancel(true) 分别改变什么？等待超时是否意味着任务停止？','CONCURRENCY','concurrency','STANDARD',
 JSON_ARRAY('Future','超时','线程中断'),JSON_ARRAY('get 超时限制等待时间','后台任务可能继续执行','cancel(true) 尝试通过中断取消'),
 'get(timeout) 限制调用线程等待结果的时间，超时返回并不自动停止后台任务。cancel(true) 会尝试取消任务，并允许对正在执行的线程发出中断。中断需要任务代码或所调用的阻塞操作响应，不能把取消请求视为强制终止线程。',
 JSON_ARRAY('把等待超时等同于后台任务终止','把 cancel(true) 当成强制杀死线程'),JSON_ARRAY('哪一个操作只限制等待结果的时间？','运行中的任务需要怎样配合中断？'),
 'EXTERNAL_REFERENCE','JavaGuide《Java 线程池最佳实践》：任务超时后会自动停止吗？','https://javaguide.cn/java/concurrent/java-thread-pool-best-practices.html'),
('qb-ref-concurrency-003','线程池两种关闭方法','shutdown 与 shutdownNow 如何处理新任务、排队任务和正在执行的任务？','CONCURRENCY','concurrency','STANDARD',
 JSON_ARRAY('Java','线程池','关闭'),JSON_ARRAY('两者都停止接收新任务','shutdown 继续处理已提交任务','shutdownNow 返回待执行任务并尝试中断运行任务'),
 'shutdown 停止接收新任务，但继续执行已经提交和排队的任务。shutdownNow 停止接收新任务，返回尚未开始执行的排队任务，并尝试中断正在执行的任务。后者依赖任务响应中断，因此方法返回不代表所有运行任务已经结束。',
 JSON_ARRAY('认为 shutdown 会直接丢弃队列','认为 shutdownNow 保证立即结束所有线程'),JSON_ARRAY('哪个方法会返回未开始执行的任务？','为什么 shutdownNow 不能保证立刻终止？'),
 'EXTERNAL_REFERENCE','JavaGuide《Java 线程池详解》：shutdown() VS shutdownNow()','https://javaguide.cn/java/concurrent/java-thread-pool-summary.html'),
('qb-ref-concurrency-004','CallerRunsPolicy 的反压与关闭行为','CallerRunsPolicy 如何影响任务提交方？线程池已经关闭时，它还会让提交方执行任务吗？','CONCURRENCY','concurrency','ADVANCED',
 JSON_ARRAY('线程池','CallerRunsPolicy','反压'),JSON_ARRAY('由提交任务的线程执行','执行时间拖慢后续提交','线程池关闭后不再执行被拒绝任务'),
 '线程池尚未关闭时，CallerRunsPolicy 让提交任务的线程同步执行被拒绝的任务。提交方因而被任务执行占用，减慢继续提交的速度，形成反压。线程池已经关闭时，该策略不会再让提交线程执行任务，而是丢弃这次被拒绝的任务。',
 JSON_ARRAY('认为 CallerRunsPolicy 在所有情况下都保证执行','认为它会创建额外的工作线程'),JSON_ARRAY('任务实际在哪个线程执行？','为什么它能影响生产任务的速度？'),
 'EXTERNAL_REFERENCE','JavaGuide《Java 线程池最佳实践》：CallerRunsPolicy 能形成背压吗？','https://javaguide.cn/java/concurrent/java-thread-pool-best-practices.html'),
('qb-ref-performance-001','EXPLAIN 的候选索引与实际索引','MySQL EXPLAIN 中，possible_keys 与 key 分别表达什么？key 为 NULL 表示什么？','PERFORMANCE','performance','BEGINNER',
 JSON_ARRAY('MySQL','EXPLAIN','索引'),JSON_ARRAY('possible_keys 表示可能使用的索引','key 表示实际选择的索引','key 为 NULL 表示未使用索引'),
 'possible_keys 列出查询可能使用的索引，key 则表示执行计划实际选择使用的索引。候选索引存在并不保证最终采用，优化器仍会选择执行方式。key 为 NULL 表示该计划没有使用索引。分析时应区分候选列表与实际计划。',
 JSON_ARRAY('把 possible_keys 当成实际使用结果','认为 key 为 NULL 说明表里没有任何索引'),JSON_ARRAY('应该看哪列确认计划实际选中了哪个索引？','存在候选索引是否保证最终使用它？'),
 'EXTERNAL_REFERENCE','JavaGuide《MySQL 执行计划分析》：possible_keys、key','https://javaguide.cn/database/mysql/mysql-query-execution-plan.html'),
('qb-ref-performance-002','EXPLAIN rows 为何不是实测值','EXPLAIN 中的 rows 表示什么？为什么不能直接把它当成查询实际扫描的精确行数？','PERFORMANCE','performance','STANDARD',
 JSON_ARRAY('MySQL','EXPLAIN','估算行数'),JSON_ARRAY('rows 是计划阶段的估算','估算使用表统计信息和索引选择','估算与真实执行可能不同'),
 'rows 表示 MySQL 估计为了找到所需行而要读取的行数，估算依据表统计信息及索引选择。它属于执行计划中的估计值，并非执行完成后逐行计数得到的测量结果，因此可能与实际扫描行数不同。',
 JSON_ARRAY('把 rows 当成精确实测行数','忽略表统计信息对估算的影响'),JSON_ARRAY('rows 的估算与哪些信息有关？','为什么两个计划的估算值需要结合执行结果理解？'),
 'EXTERNAL_REFERENCE','JavaGuide《MySQL 执行计划分析》：rows','https://javaguide.cn/database/mysql/mysql-query-execution-plan.html'),
('qb-ref-performance-003','Actuator 线程报告与指标端点','《Spring 实战》第 5 版列出的 /threaddump、/metrics 和 /metrics/{name} 分别返回什么？','PERFORMANCE','performance','BEGINNER',
 JSON_ARRAY('Spring Boot','Actuator','线程报告'),JSON_ARRAY('threaddump 返回线程报告','metrics 返回指标分类列表','metrics/name 返回指定指标的多维值'),
 '书中的 /threaddump 返回应用所有线程的报告；/metrics 返回所有指标分类的列表；/metrics/{name} 返回指定指标的多维度值集。需要查看线程状态与执行情况时关注线程报告，需要查看指标名称和具体指标值时使用对应的 metrics 端点。',
 JSON_ARRAY('认为 metrics 列表就是所有线程的调用栈','混淆指标分类列表与某个指标的具体值'),JSON_ARRAY('哪个端点列出指标分类？','哪个端点提供应用线程报告？'),
 'EXTERNAL_REFERENCE','《Spring 实战》第 5 版，16.1 Actuator 概览，PDF 第 620 页','https://www.manning.com/books/spring-in-action-fifth-edition'),
('qb-ref-reliability-003','去重记录与业务操作的事务边界','用数据库去重表实现幂等时，为什么去重记录写入和业务操作应该处于同一事务？','RELIABILITY','reliability','ADVANCED',
 JSON_ARRAY('幂等','去重表','数据库事务'),JSON_ARRAY('唯一约束拦截重复请求','去重写入和业务操作共同提交','业务失败时去重记录一起回滚'),
 '去重表通过请求标识及唯一约束识别重复操作。去重记录与业务操作应在同一事务中提交，使“已记录”对应“业务已完成”。业务失败时二者一起回滚，后续请求仍可重试；如果只提交去重记录，失败的业务可能被错误判断为已经处理。',
 JSON_ARRAY('先独立提交去重记录再执行业务','把去重表插入成功等同于业务已经成功'),JSON_ARRAY('业务回滚时去重记录应发生什么？','去重表依靠什么约束处理重复插入？'),
 'EXTERNAL_REFERENCE','JavaGuide《接口幂等性》：去重表','https://javaguide.cn/high-availability/idempotency.html');

INSERT INTO question_bank_versions (question_id,version,content_json,change_note)
SELECT id,version,JSON_OBJECT(
 'id',id,'version',version,'title',title,'question',question,'topic',topic,'competencyId',competency_id,
 'difficulty',difficulty,'tags',tags_json,'keyPoints',key_points_json,'referenceAnswer',reference_answer,
 'commonMistakes',common_mistakes_json,'followUps',follow_ups_json,
 'sourceType',source_type,'sourceTitle',source_title,'sourceUrl',source_url),
 '根据 JavaGuide、小林 coding 与 Spring 实战原文新增参考题'
FROM question_bank WHERE id LIKE 'qb-ref-%';
